import { normalizeCameraPreferences, normalizeModeZoom } from './camera-preferences.mjs';
import { pickDeviceSettings } from './privacy-data.mjs';

export const $=id=>document.getElementById(id);
export const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=n=>Math.round(Number(n)||0).toLocaleString();
export function actionButton(label,fn,{secondary=false,disabled=false,title=''}={}){const b=document.createElement('button');b.className=secondary?'button-secondary':'button-primary';b.textContent=label;b.disabled=disabled;b.title=title;b.addEventListener('click',fn);return b;}
export class Dialog{
 constructor({onOpen=()=>{},onClose=()=>{}}={}){this.backdrop=$('modalBackdrop');this.el=$('modal');this.body=$('modalBody');this.onOpen=onOpen;this.onClose=onClose;this.opened=false;this.kind=null;$('closeModal').onclick=()=>this.close();this.backdrop.addEventListener('click',e=>{if(e.target===this.backdrop)this.close();});this.el.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();this.close();}if(e.key==='Tab'){const list=[...this.el.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]')].filter(x=>x.offsetParent!==null),first=list[0],last=list.at(-1);if(!first){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===first||document.activeElement===this.el)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});}
 open(title,kind='dialogue',{eyebrow='SHIP COMPUTER',wide=false}={}){if(!this.opened)this.previousFocus=document.activeElement;this.opened=true;this.kind=kind;this.backdrop.hidden=false;this.el.classList.toggle('wide',wide);$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;this.body.replaceChildren();this.body.scrollTop=0;this.onOpen();this.el.focus({preventScroll:true});return this.body;}
 close(){if(!this.opened)return;const kind=this.kind;this.opened=false;this.kind=null;this.backdrop.hidden=true;this.onClose(kind);this.previousFocus?.focus?.({preventScroll:true});}
 html(markup){this.body.innerHTML=markup;return this.body;}
 choices(items){const list=document.createElement('div');list.className='choice-list';items.forEach((item,i)=>{const b=document.createElement('button');b.className=`choice ${item.warning?'warning':''}`;b.disabled=!!item.disabled;b.innerHTML=`<span class="choice-index">${String(i+1).padStart(2,'0')}</span><span><strong>${escapeHtml(item.label)}</strong>${item.detail?`<small>${escapeHtml(item.detail)}</small>`:''}</span>`;b.onclick=item.action;list.append(b);});this.body.append(list);return list;}
}
export const STORAGE_KEY='dfe.farwake.save.v1';
export function readSave(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;const parsed=JSON.parse(raw);return parsed?.state??parsed;}catch{return null;}}
export function saveGame(game){try{const serialized=game.serialize();localStorage.setItem(STORAGE_KEY,typeof serialized==='string'?serialized:JSON.stringify(serialized));$('saveState').textContent='SAVED JUST NOW';return true;}catch{$('saveState').textContent='SAVE UNAVAILABLE';return false;}}
export function readSettings(){
 const defaults={guidance:'simple',controlScale:1,textScale:1,...normalizeCameraPreferences(),immersiveHud:true,translucentHud:true,compactTips:true,sound:true,music:true,reduceMotion:window.matchMedia('(prefers-reduced-motion: reduce)').matches,leftHanded:false,flightAssist:true,showPerformance:false};
 try{const raw=pickDeviceSettings(JSON.parse(localStorage.getItem('dfe.farwake.settings.v1')||'{}'),{includeLegacy:true}),legacy={shipZoom:normalizeModeZoom(raw?.worldZoom,'ship'),personZoom:normalizeModeZoom(raw?.worldZoom,'person')};const settings={...defaults,...raw,...normalizeCameraPreferences(raw,legacy)};delete settings.worldZoom;return settings;}catch{return defaults;}
}
export function applySettings(settings,{cameraPreferences=settings}={}){
 settings.textScale=Math.max(1,Math.min(1.6,Number(settings.textScale)||1));settings.controlScale=Math.max(.8,Math.min(1.2,Number(settings.controlScale)||1));Object.assign(settings,normalizeCameraPreferences(settings));delete settings.worldZoom;
 for(const[key,className]of [['immersiveHud','immersive-hud'],['translucentHud','translucent-hud'],['compactTips','compact-tips']]){if(typeof settings[key]!=='boolean')settings[key]=true;document.body.classList.toggle(className,settings[key]);}
 document.body.classList.toggle('large-text',settings.textScale>=1.25);document.documentElement.style.setProperty('--control-scale',String(settings.controlScale));document.documentElement.style.setProperty('--font-scale',String(settings.textScale));document.body.classList.toggle('left-handed',!!settings.leftHanded);document.body.classList.toggle('reduce-motion',!!settings.reduceMotion);
 // Shared captains and practice use their own camera scope. Device controls and
 // accessibility still save here without replacing this browser's solo camera.
 try{localStorage.setItem('dfe.farwake.settings.v1',JSON.stringify(pickDeviceSettings({...settings,...normalizeCameraPreferences(cameraPreferences)})));}catch{}
}
export function toast(message,type='info',duration=4600){if(!message)return;const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=message;$('toastStack').append(e);while($('toastStack').children.length>4)$('toastStack').firstChild.remove();setTimeout(()=>e.remove(),duration);}
export function portrait(canvas,color='#83cbbb',seed=1){const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#162635';c.fillRect(0,0,32,40);c.fillStyle='#293f4d';for(let i=0;i<7;i++){c.fillRect((i*7+seed*3)%32,i*6,4,1);}c.fillStyle='#0c1923';c.fillRect(6,31,21,9);c.fillStyle=color;c.fillRect(7,28,18,12);c.fillRect(4,31,6,9);c.fillRect(24,31,5,9);c.fillStyle='#384c5b';c.fillRect(15,28,3,12);c.fillStyle='#deb48e';c.fillRect(10,9,13,17);c.fillRect(8,14,3,8);c.fillRect(23,14,2,7);c.fillStyle='#be8f71';c.fillRect(10,22,13,4);c.fillRect(14,26,6,4);c.fillStyle=['#706457','#352b2b','#a6a294','#4e453e'][seed%4];c.fillRect(9,5,15,7);c.fillRect(7,9,5,7);c.fillRect(22,9,3,6);c.fillStyle='#1e2930';c.fillRect(12,16,2,2);c.fillRect(20,16,2,2);c.fillStyle='#785a4b';c.fillRect(15,22,5,1);c.fillStyle='#ead3a0';c.fillRect(10,31,3,2);}
